// ========== drums ==========
// Crescendo · bars 1-11 · pattern D
// Drums · RolandTR909
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.9).distort(1).distortvol(.5).mask(section1).velocity(section1).orbit(1).analyze("kick")
$: s("~ [cp ~ ~ ~] ~ [cp ~ ~ cp]").bank("RolandTR909").gain(0.72).distort(1).distortvol(.5).mask(section1).velocity(section1).orbit(1).analyze("snare")
